import"./chunk-VC46IEJQ.js";var e=(n,r,t,a,i,l,s,o,h)=>({name:{en:n,zh:r},desc:{en:t[0],zh:t[1]},tour:{en:a[0],zh:a[1]},source:{confidence:i,refs:l,book:{en:s[0],zh:s[1]},unknown:{en:o[0],zh:o[1]},interpretation:{en:h[0],zh:h[1]}}}),d={id:"asshai",intro:{en:"Asshai-by-the-Shadow lies at the far south-eastern edge of the known world, an ancient port of black stone where the Shadow Lands meet the sea. The novels only name it, so this scene is a quiet, deliberately sparse interpretation.",zh:"\u9634\u5F71\u4E4B\u5730\u4E9A\u590F\u4F4D\u4E8E\u5DF2\u77E5\u4E16\u754C\u7684\u4E1C\u5357\u5C3D\u5934\uFF0C\u662F\u9634\u5F71\u4E4B\u5730\u4E34\u6D77\u5904\u4E00\u5EA7\u9ED1\u77F3\u7B51\u6210\u7684\u53E4\u8001\u6E2F\u57CE\u3002\u5C0F\u8BF4\u53EA\u63D0\u5176\u540D\uFF0C\u6240\u4EE5\u672C\u573A\u666F\u662F\u4E00\u4EFD\u523B\u610F\u514B\u5236\u3001\u5B89\u9759\u7684\u60F3\u8C61\u3002"},notes:{en:'In the novels Asshai is little more than a name: Melisandre is "of Asshai", Quaithe is a shadowbinder from there, and its caravans reach Vaes Dothrak. The companion book adds a city of greasy black stone that seems to drink the light, walls far too large for its small population, and a site where the river Ash meets the sea beside the Shadow Lands. Everything shown here - street plan, towers, lights, the shape of the Shadow - is interpretation.',zh:"\u5728\u5C0F\u8BF4\u91CC\uFF0C\u4E9A\u590F\u51E0\u4E4E\u53EA\u662F\u4E00\u4E2A\u540D\u5B57\uFF1A\u6885\u4E3D\u73CA\u5353\u53F7\u79F0\u201C\u6765\u81EA\u4E9A\u590F\u201D\uFF0C\u7F1A\u5F71\u58EB\u9B41\u6670\u51FA\u8EAB\u4E8E\u6B64\uFF0C\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u4E5F\u6709\u6765\u81EA\u4E9A\u590F\u7684\u5546\u961F\u3002\u8BBE\u5B9A\u96C6\u8865\u5145\u9053\uFF1A\u5168\u57CE\u4EE5\u6CB9\u817B\u3001\u4EFF\u4F5B\u541E\u566C\u5149\u7EBF\u7684\u9ED1\u77F3\u7B51\u6210\uFF0C\u57CE\u5899\u4E4B\u5927\u8FDC\u8D85\u5176\u5BE5\u5BE5\u4EBA\u53E3\uFF0C\u5750\u843D\u5728\u963F\u4EC0\u6CB3\u5165\u6D77\u5904\u3001\u9634\u5F71\u4E4B\u5730\u4E4B\u7554\u3002\u753B\u9762\u4E2D\u7684\u4E00\u5207\u2014\u2014\u8857\u9053\u5E03\u5C40\u3001\u5854\u697C\u3001\u706F\u706B\u3001\u9634\u5F71\u4E4B\u5730\u7684\u5F62\u8C8C\u2014\u2014\u5747\u4E3A\u60F3\u8C61\u3002"},tour:["black-harbour","dark-stone-streets","warlock-towers","pale-lights","ruined-quarter","the-shadow"],sources:[{ref:"acok",checked:"memory",note:{en:'Melisandre "of Asshai" and Quaithe of the Shadow are introduced; the city itself is not described. Recalled only generally.',zh:"\u4E66\u4E2D\u51FA\u73B0\u201C\u6765\u81EA\u4E9A\u590F\u7684\u201D\u6885\u4E3D\u73CA\u5353\u4E0E\u6765\u81EA\u9634\u5F71\u4E4B\u5730\u7684\u9B41\u6670\uFF0C\u4F46\u57CE\u5E02\u672C\u8EAB\u672A\u89C1\u63CF\u5199\u3002\u4EC5\u51ED\u5927\u81F4\u5370\u8C61\u3002"}},{ref:"adwd",checked:"memory",note:{en:"Quaithe is called a shadowbinder of Asshai; still no description of the city. Recalled only generally.",zh:"\u9B41\u6670\u88AB\u79F0\u4E3A\u4E9A\u590F\u7684\u7F1A\u5F71\u58EB\uFF1B\u57CE\u5E02\u672C\u8EAB\u4F9D\u65E7\u672A\u89C1\u63CF\u5199\u3002\u4EC5\u51ED\u5927\u81F4\u5370\u8C61\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Wiki search summaries citing the companion: oily black stone that seems to drink light, walls able to hold a vast population but only a market town's worth of people, the Ash and the Shadow Lands. The book itself was not checked.",zh:"\u636E\u5F15\u7528\u8BBE\u5B9A\u96C6\u7684\u7EF4\u57FA\u641C\u7D22\u6458\u8981\uFF1A\u6CB9\u817B\u9ED1\u77F3\u4F3C\u80FD\u541E\u566C\u5149\u7EBF\uFF1B\u57CE\u5899\u53EF\u5BB9\u7EB3\u5E9E\u5927\u4EBA\u53E3\uFF0C\u5B9E\u9645\u5C45\u6C11\u5374\u53EA\u6709\u4E00\u5EA7\u96C6\u9547\u4E4B\u6570\uFF1B\u963F\u4EC0\u6CB3\u4E0E\u9634\u5F71\u4E4B\u5730\u3002\u672A\u67E5\u9605\u539F\u4E66\u3002"}}],landmarks:{"black-harbour":e("Black Harbour","\u9ED1\u77F3\u6E2F",["A long quay of black stone where ships from distant seas put in beneath silent towers.","\u9ED1\u77F3\u780C\u6210\u7684\u957F\u7801\u5934\uFF0C\u8FDC\u65B9\u6765\u7684\u8239\u53EA\u5728\u5BC2\u9759\u7684\u5854\u697C\u4E0B\u9760\u5CB8\u3002"],["Ships from the far side of the world end their voyages at these black quays.","\u6765\u81EA\u4E16\u754C\u53E6\u4E00\u7AEF\u7684\u8239\u53EA\uFF0C\u5728\u8FD9\u4E9B\u9ED1\u8272\u7801\u5934\u7ED3\u675F\u822A\u7A0B\u3002"],"low",["twoiaf"],["Asshai is a port where the Ash meets the sea; its harbour is not described.","\u4E9A\u590F\u662F\u963F\u4EC0\u6CB3\u5165\u6D77\u5904\u7684\u6E2F\u53E3\uFF1B\u6E2F\u533A\u672A\u89C1\u63CF\u5199\u3002"],["Harbour layout and size.","\u6E2F\u53E3\u5E03\u5C40\u4E0E\u89C4\u6A21\u3002"],["One straight black quay with a few piers and two guard towers.","\u4E00\u9053\u7B14\u76F4\u7684\u9ED1\u8272\u7801\u5934\uFF0C\u51E0\u5EA7\u6808\u6865\u4E0E\u4E24\u5EA7\u5B88\u671B\u5854\u3002"]),"dark-stone-streets":e("Black Stone Streets","\u9ED1\u77F3\u8857\u5DF7",["Narrow lanes of black stone houses climbing from the harbour.","\u81EA\u6E2F\u53E3\u5411\u4E0A\u6500\u5347\u7684\u72ED\u7A84\u8857\u5DF7\uFF0C\u4E24\u65C1\u662F\u9ED1\u77F3\u623F\u5C4B\u3002"],["The stone here seems to swallow the light; the lanes stay dim at noon.","\u8FD9\u91CC\u7684\u77F3\u5934\u4EFF\u4F5B\u541E\u566C\u5149\u7EBF\uFF0C\u6B63\u5348\u65F6\u5206\u8857\u5DF7\u4F9D\u7136\u660F\u6697\u3002"],"medium",["twoiaf"],["The city's buildings, streets and walls are of greasy black stone that seems to drink the light.","\u57CE\u4E2D\u5EFA\u7B51\u3001\u8857\u9053\u4E0E\u57CE\u5899\u7686\u4EE5\u6CB9\u817B\u7684\u9ED1\u77F3\u7B51\u6210\uFF0C\u4EFF\u4F5B\u80FD\u541E\u566C\u5149\u7EBF\u3002"],["The street plan and building shapes.","\u8857\u9053\u5E03\u5C40\u4E0E\u5EFA\u7B51\u9020\u578B\u3002"],["A loose cluster of tall and domed dark houses along three lanes.","\u6CBF\u4E09\u6761\u5C0F\u5DF7\u5206\u5E03\u7684\u9AD8\u5C4B\u4E0E\u5706\u9876\u5C4B\uFF0C\u4E00\u5F8B\u6697\u8272\u3002"]),"warlock-towers":e("Sorcerers' Towers","\u672F\u58EB\u4E4B\u5854",["Tall, tapering spires, imagined as the homes of shadowbinders and sorcerers, with faint light high up.","\u9AD8\u8038\u6536\u7A84\u7684\u5C16\u5854\uFF0C\u60F3\u8C61\u4E3A\u7F1A\u5F71\u58EB\u4E0E\u672F\u58EB\u7684\u5C45\u6240\uFF0C\u9AD8\u5904\u9690\u6709\u5FAE\u5149\u3002"],["Asshai is famed for shadowbinders and sorcerers; we imagine their towers here.","\u4E9A\u590F\u4EE5\u7F1A\u5F71\u58EB\u4E0E\u672F\u58EB\u95FB\u540D\uFF1B\u6211\u4EEC\u5728\u6B64\u60F3\u8C61\u51FA\u4ED6\u4EEC\u7684\u5854\u3002"],"low",["acok","adwd"],["Shadowbinders, red priests and other sorcerers are linked to Asshai; their dwellings are not described.","\u7F1A\u5F71\u58EB\u3001\u7EA2\u888D\u50E7\u53CA\u5176\u4ED6\u672F\u58EB\u90FD\u4E0E\u4E9A\u590F\u6709\u5173\uFF1B\u5176\u5C45\u6240\u672A\u89C1\u63CF\u5199\u3002"],["Where they live and what their buildings look like.","\u4ED6\u4EEC\u4F4F\u5728\u4F55\u5904\uFF0C\u5EFA\u7B51\u53C8\u662F\u4F55\u6A21\u6837\u3002"],["Five narrow black spires; invented.","\u4E94\u5EA7\u7EC6\u957F\u7684\u9ED1\u5854\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"pale-lights":e("Pale Lights","\u82CD\u767D\u706F\u706B",["A few cold lights high in the towers, the only sign that anyone is watching.","\u5854\u697C\u9AD8\u5904\u7684\u51E0\u70B9\u51B7\u5149\uFF0C\u662F\u552F\u4E00\u663E\u793A\u6709\u4EBA\u5B88\u671B\u7684\u8FF9\u8C61\u3002"],["Someone, or something, keeps watch up there.","\u90A3\u4E0A\u9762\u6709\u4EBA\u2014\u2014\u6216\u522B\u7684\u4EC0\u4E48\u2014\u2014\u5728\u5B88\u671B\u3002"],"low",["twoiaf"],["Nothing establishes these lights.","\u6CA1\u6709\u4EFB\u4F55\u8BB0\u8F7D\u63D0\u5230\u8FD9\u4E9B\u706F\u706B\u3002"],["Whether any such lights exist.","\u662F\u5426\u5B58\u5728\u8FD9\u6837\u7684\u706F\u706B\u3002"],["Purely an invented mood element.","\u7EAF\u4E3A\u8425\u9020\u6C1B\u56F4\u800C\u8BBE\u3002"]),"ruined-quarter":e("Empty Quarter","\u7A7A\u57CE\u533A",["Roofless shells and fallen walls in a district long abandoned.","\u65E9\u5DF2\u5E9F\u5F03\u7684\u8857\u533A\uFF0C\u53EA\u5269\u65E0\u9876\u7684\u7A7A\u58F3\u4E0E\u5012\u584C\u7684\u5899\u57A3\u3002"],["Asshai's walls could hold a vast city; far fewer people live here now.","\u4E9A\u590F\u7684\u57CE\u5899\u8DB3\u4EE5\u5BB9\u7EB3\u4E00\u5EA7\u5DE8\u57CE\uFF0C\u5982\u4ECA\u4F4F\u5728\u8FD9\u91CC\u7684\u4EBA\u5374\u5BE5\u5BE5\u65E0\u51E0\u3002"],"low",["twoiaf"],["The walls enclose room for a huge population, but only a market town's worth of people live inside.","\u57CE\u5899\u5185\u8DB3\u4EE5\u5BB9\u7EB3\u5E9E\u5927\u4EBA\u53E3\uFF0C\u5B9E\u9645\u5C45\u6C11\u5374\u53EA\u6709\u4E00\u5EA7\u96C6\u9547\u4E4B\u6570\u3002"],["Which districts stand empty and whether they are ruined.","\u54EA\u4E9B\u8857\u533A\u7A7A\u7F6E\uFF0C\u662F\u5426\u5DF2\u6210\u5E9F\u589F\u3002"],["A scatter of low broken walls on the south-east slope.","\u4E1C\u5357\u5761\u4E0A\u6563\u843D\u7684\u4F4E\u77EE\u65AD\u5899\u3002"]),"the-shadow":e("The Shadow","\u9634\u5F71\u4E4B\u5730",["The dark, mountainous land behind the city that gives it its name.","\u57CE\u540E\u90A3\u7247\u5E7D\u6697\u591A\u5C71\u7684\u571F\u5730\uFF0C\u57CE\u540D\u4FBF\u7531\u6B64\u800C\u6765\u3002"],["Beyond the city the land goes dark, and few return from there.","\u57CE\u5916\u7684\u5927\u5730\u4E00\u7247\u5E7D\u6697\uFF0C\u9C9C\u6709\u4EBA\u4ECE\u90A3\u91CC\u5F52\u6765\u3002"],"low",["twoiaf","adwd"],["The Shadow Lands, a mountainous region beyond Asshai, are known only by reputation.","\u9634\u5F71\u4E4B\u5730\u662F\u4E9A\u590F\u80CC\u540E\u7684\u4E00\u7247\u5C71\u533A\uFF0C\u4E16\u4EBA\u53EA\u95FB\u5176\u540D\u3002"],["What the Shadow really is.","\u9634\u5F71\u4E4B\u5730\u7A76\u7ADF\u662F\u4EC0\u4E48\u3002"],["Black crags suggest the Shadow; no creatures are shown.","\u4EE5\u9ED1\u8272\u5CED\u58C1\u6697\u793A\u9634\u5F71\u4E4B\u5730\uFF0C\u4E0D\u753B\u4EFB\u4F55\u751F\u7269\u3002"])}};export{d as default};
